import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { createMeeting, getUsers } from '../../api';

function HodSchedule({ user }) {
  const navigate = useNavigate();
  const [staffList, setStaffList] = useState([]);
  const [form, setForm] = useState({ title: '', agenda: '', date: '', time: '', meetingLink: '', venue: '', selectedStaff: [] });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getUsers().then(r => setStaffList(r.data.filter(u => u.role === 'staff' && !u.isBlacklisted))).catch(console.error);
  }, []);

  const toggle = (id) => {
    setForm(f => ({ ...f, selectedStaff: f.selectedStaff.includes(id) ? f.selectedStaff.filter(x => x !== id) : [...f.selectedStaff, id] }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); setError('');
    if (!form.title || !form.date || !form.time) return setError('Title, date and time are required');
    setLoading(true);
    try {
      await createMeeting({ title: form.title, agenda: form.agenda, date: form.date, time: form.time, meetingLink: form.meetingLink, venue: form.venue, attendees: form.selectedStaff });
      alert('Meeting scheduled!');
      navigate('/hod/dashboard');
    } catch (err) { setError(err.response?.data?.message || 'Failed'); }
    finally { setLoading(false); }
  };

  return (
    <div className="bg-wrapper">
      <div className="bg-content">
        <h1 className="page-title text-green" style={{ textAlign: 'center' }}>Schedule Meeting (HOD)</h1>
        <p style={{ textAlign: 'center', color: '#555', marginBottom: '1.5rem' }}>
          Department: <strong>{user.department}</strong>
        </p>

        <div className="card" style={{ maxWidth: '680px', margin: '0 auto' }}>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Meeting Title *</label>
              <input type="text" placeholder="e.g. Department Review Meeting" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} required />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
              <div className="form-group">
                <label>Meeting Date *</label>
                <input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} required />
              </div>
              <div className="form-group">
                <label>Meeting Time *</label>
                <input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} required />
              </div>
            </div>

            <div className="form-group">
              <label>Agenda / Topic</label>
              <textarea rows="3" placeholder="Enter meeting agenda or topic..." value={form.agenda} onChange={e => setForm({ ...form, agenda: e.target.value })} />
            </div>

            <div className="form-group">
              <label>Meeting Link</label>
              <input type="text" placeholder="https://meet.google.com/xxx-xxxx-xxx" value={form.meetingLink} onChange={e => setForm({ ...form, meetingLink: e.target.value })} />
            </div>

            <div className="form-group">
              <label>Venue (optional)</label>
              <input type="text" placeholder="e.g. Seminar Hall, Room 201" value={form.venue} onChange={e => setForm({ ...form, venue: e.target.value })} />
            </div>

            <div className="form-group">
              <label>Select Staff — {form.selectedStaff.length} selected</label>
              <div style={{ border: '1px solid #d1d5db', borderRadius: '8px', maxHeight: '180px', overflowY: 'auto', padding: '0.4rem' }}>
                {staffList.length === 0 ? (
                  <p style={{ padding: '0.5rem', color: '#6b7280', fontSize: '0.85rem' }}>No staff available</p>
                ) : staffList.map(s => (
                  <label key={s._id} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.4rem 0.6rem', borderRadius: '6px', cursor: 'pointer', background: form.selectedStaff.includes(s._id) ? '#dbeafe' : 'white' }}>
                    <input type="checkbox" checked={form.selectedStaff.includes(s._id)} onChange={() => toggle(s._id)} />
                    {s.name} — {s.email}
                  </label>
                ))}
              </div>
            </div>

            {error && <div className="alert alert-error">❌ {error}</div>}

            <button type="submit" className="btn btn-green" disabled={loading} style={{ width: '100%', padding: '0.9rem', fontSize: '1rem' }}>
              {loading ? 'Scheduling...' : '📅 Schedule Meeting'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

export default HodSchedule;
